/// <summary>
/// Extension of GUPItemBasePriceCalcJob
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceCalcJob_All))]
internal final class METGUPItemBasePriceCalcJob_All_extension
{
}

Method.Source:
/// <summary>
/// run method
/// </summary>
public void run()
{
    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::BasePriceCalculation);

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        next run();

        if (this.parmMETIncludeClaimFromVendor())
        {
            METVendClaimProcessJob::contructMETVendClaimProcessTasks(this.parmCalcDate(), this.parmSiteId(), this);
        }

        procMetrics.endTrace();
    }
}

public void progressInit(
    str                 caption,
    int64               total,
    str                 animation,
    int                 numOfBars,
    FormBuildControl    embedded
    )
{
    METProcMetrics procMetrics = METProcMetricsScope::current();

    if (procMetrics)
    {
        procMetrics.setTotalCount(total);
        procMetrics.setSessionGuid(this.parmSessionGuid());
        procMetrics.beginTrace(caption);
        //Or use procMetrics start trace method: pass count & description to set and start the log in one call
    }

    next progressInit(caption, total, animation, numOfBars, embedded);
}
